const updateCustomFieldDef = `-- name: UpdateCustomFieldDef :one
UPDATE custom_field_defs SET label = $1, options = $2, required = $3, sort_order = $4,
  version = version + 1
WHERE id = $5 AND organization_id = $6 AND version = $7
RETURNING id, organization_id, key, label, kind, options, required, sort_order, created_at, updated_at, version
`

type UpdateCustomFieldDefParams struct {
	Label          string
	Options        []string
	Required       bool
	SortOrder      int32
	ID             pgtype.UUID
	OrganizationID pgtype.UUID
	Version        int32
}

func (q *Queries) UpdateCustomFieldDef(ctx context.Context, arg UpdateCustomFieldDefParams) (CustomFieldDef, error) {
	row := q.db.QueryRow(ctx, updateCustomFieldDef,
		arg.Label,
		arg.Options,
		arg.Required,
		arg.SortOrder,
		arg.ID,
		arg.OrganizationID,
		arg.Version,
	)
	var i CustomFieldDef
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.Key,
		&i.Label,
		&i.Kind,
		&i.Options,
		&i.Required,
		&i.SortOrder,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Version,
	)
	return i, err
}

